function ValueRow({
  indent = false,
  row,
}: {
  indent?: boolean;
  row: TableRowData;
}) {
  const cell = (value: Json | undefined) => (
    <TableCell className="truncate">
      {value === undefined ? (
        <span className="text-muted-foreground">—</span>
      ) : (
        <Value value={value} />
      )}
    </TableCell>
  );

  return (
    <TableRow className="hover:bg-transparent">
      <TableCell
        className={cn(
          "truncate text-muted-foreground",
          indent ? "ps-8" : "ps-4",
        )}
      >
        {row.path}
      </TableCell>
      {same(row.a, row.b) ? (
        <TableCell className="truncate text-muted-foreground" colSpan={2}>
          <Value value={row.a} />
        </TableCell>
      ) : (
        <>
          {cell(row.a)}
          {cell(row.b)}
        </>
      )}
    </TableRow>
  );
}

function JsonSideBySide({ left, right, only }: CompareProps) {
  const { folds, toggle } = useFolds();
  const { copied, copy } = useCopy();
  const rows = toRows(left.value, right.value, { folds, only });

  return (
    <div className="overflow-hidden rounded-lg border">
      <div className="grid grid-cols-2 divide-x border-b bg-muted/60">
        {[left, right].map((side) => (
          <div
            className="flex h-10 items-center justify-between ps-4 pe-1.5 text-xs font-medium text-muted-foreground"
            key={side.label}
          >
            {side.label}
            <CopyButton
              copied={copied === side.label}
              label={`Copy ${side.label}`}
              onCopy={() => void copy(side.label, side.value)}
            />
          </div>
        ))}
      </div>

      <div className="py-2 font-mono text-xs leading-relaxed">
        {rows.map((row) => (
          <div
            className={cn(
              "grid grid-cols-2 divide-x border-s-2",
              row.differs ? "border-s-primary" : "border-s-transparent",
            )}
            key={row.id}
          >
            <div className="flex min-w-0 items-center ps-1.5 pe-3">
              <Fold line={row.left} onToggle={toggle} />
              {row.left ? <Code line={row.left} muted={!row.differs} /> : null}
            </div>
            <div className="flex min-w-0 items-center ps-4 pe-3">
              {row.right ? (
                <Code line={row.right} muted={!row.differs} />
              ) : null}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import * as React from "react";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from "@/lib/utils";

type ReferenceColumn = {
  header: string;
  /** A literal width class: Tailwind only emits utilities it sees spelled out. Omit on the column that takes the remaining width. */
  width?: string;
};

export type ReferenceRow = {
  key: string;
  cells: React.ReactNode[];
};

export function ReferenceTable({
  columns,
  rows,
}: {
  columns: ReferenceColumn[];
  rows: ReferenceRow[];
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      {/* table-fixed so a long cell cannot widen its column past the declared width. */}
      <Table className="table-fixed">
        <TableHeader>
          <TableRow className="bg-muted/40 hover:bg-muted/40">
            {columns.map((column) => (
              <TableHead
                className={cn(
                  "h-11 px-4 text-xs font-medium text-muted-foreground",
                  column.width,
                )}
                key={column.header}
              >
                {column.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.key}>
              {row.cells.map((cell, index) => (
                <TableCell
                  /* `whitespace-normal` undoes the primitive's nowrap so prose stays inside the declared width. */
                  className="px-4 py-3.5 align-top whitespace-normal"
                  key={columns[index]?.header ?? index}
                >
                  {cell}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

export function ReferenceName({ children }: { children: React.ReactNode }) {
  return <span className="font-mono text-sm">{children}</span>;
}

export function ReferenceLabel({ children }: { children: React.ReactNode }) {
  return <span className="text-sm font-medium">{children}</span>;
}

export function ReferenceNote({ children }: { children: React.ReactNode }) {
  return (
    <span className="text-sm leading-relaxed text-muted-foreground">
      {children}
    </span>
  );
}

